    G = [FT(e) for e in E]
    V = [r for r in UNIV() if all(g[r[0]] == r[1] for g in G)]
    used = set(g[0] for g in G)
    rng = random.Random(clue)
    for _ in range(300000):
        g = RP(rng)
        if g is None:
            continue
